import { Box, Flex } from "@chakra-ui/react";
import { useCallback, useEffect } from "react";
import { useConversationData } from "../hooks/useConversationData";
import { useIsLargeScreen } from "../hooks/useIsLargeScreen";
import type { UnionEventType } from "../types";
import { InspectorView } from "../types/inspector";
import {
  useInspectorStore,
  toggleSelectedElement,
  clearSelectedElement,
  setInspectorView,
} from "../store";
import { selectIsMantleEngine } from "../store/selectors";
import { ChatSection } from "./ChatSection";
import { EventDetails } from "./EventDetails";
import { HistorySection } from "./HistorySection";
import { MemorySection } from "./MemorySection";
import { MiddlePane } from "./MiddlePane";

const SIDE_PANEL_MAX_WIDTH = "420px";

type Props = {
  onInspectModeChange?: (inspectMode: boolean) => void;
};

export function TryAssistant({ onInspectModeChange }: Readonly<Props>) {
  const flowView = useInspectorStore((s) => s.inspectMode);
  const inspectorView = useInspectorStore((s) => s.inspectorView);
  const selectedElement = useInspectorStore((s) => s.selectedElement);
  const flows = useInspectorStore((s) => s.flows);
  const isMantleEngine = useInspectorStore(selectIsMantleEngine);

  const isEmbedded = useInspectorStore((s) => s.isEmbedded);
  const isLargeScreen = useIsLargeScreen();
  const showAllLayout = flowView && isLargeScreen && inspectorView === InspectorView.All;

  const containerProps = isEmbedded
    ? {
        flexGrow: "1",
        bg: "bg.panel",
        borderRadius: "2xl",
        overflow: "hidden" as const,
      }
    : {
        height: "100%",
        bg: "bg.panel",
        borderRadius: "2xl",
        overflow: "hidden" as const,
      };

  useConversationData();

  useEffect(() => {
    onInspectModeChange?.(flowView);
  }, [flowView, onInspectModeChange]);

  useEffect(() => {
    if (isLargeScreen && flowView && inspectorView !== InspectorView.All) {
      setInspectorView(InspectorView.All);
    }
    // Runs when inspect mode toggles on AND when the window grows into the
    // large-screen layout — the symmetric down-switch below handles shrinking.
    // Without the isLargeScreen dep, growing a small window kept the compact
    // layout, whose middle pane has no width cap.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [flowView, isLargeScreen]);

  useEffect(() => {
    if (!isLargeScreen && inspectorView === InspectorView.All) {
      setInspectorView(InspectorView.ActiveFlow);
    }
  }, [isLargeScreen, inspectorView]);

  const handleSelect = useCallback(
    (selection: UnionEventType) => toggleSelectedElement(selection),
    [],
  );

  const separatorColor = "border.emphasized";
  const panelBorderLeft = {
    borderLeft: "1px solid",
    borderColor: separatorColor,
  };

  const chatPanelStyles = {
    bg: "bg.panel",
    flexBasis: flowView ? SIDE_PANEL_MAX_WIDTH : "100%",
    flexShrink: "1",
    flexGrow: "0",
    maxWidth: flowView ? SIDE_PANEL_MAX_WIDTH : "unset",
  };

  if (showAllLayout) {
    return (
      // The skill document is capped at 768px (the pane, not just its text) and
      // the CONTAINER caps at the trio's width (two side panels + document), so
      // the white sheet hugs the panels and centers on a large monitor instead
      // of stretching across it. The v1 flow canvas keeps the full width — a
      // graph benefits from the space, prose does not.
      <Flex
        {...containerProps}
        width="100%"
        maxWidth={isMantleEngine ? `calc(2 * ${SIDE_PANEL_MAX_WIDTH} + 48rem)` : undefined}
        marginX={isMantleEngine ? "auto" : undefined}
        data-testid="try-assistant-container"
      >
        <Box css={chatPanelStyles} minWidth={0}>
          <ChatSection handleSelect={handleSelect} />
        </Box>

        <Box
          css={panelBorderLeft}
          flex="1"
          maxWidth={isMantleEngine ? "3xl" : undefined}
          minWidth={0}
          data-testid="inspector-canvas"
        >
          <MiddlePane />
        </Box>

        <Flex
          css={panelBorderLeft}
          flex={`0 1 ${SIDE_PANEL_MAX_WIDTH}`}
          maxWidth={SIDE_PANEL_MAX_WIDTH}
          minWidth={0}
          direction="column"
          data-testid="inspector-side-panel"
        >
          {selectedElement ? (
            <EventDetails event={selectedElement} onClose={clearSelectedElement} flows={flows} />
          ) : (
            <>
              <Box flex="1" minHeight={0} overflow="hidden">
                <HistorySection />
              </Box>
              {/* The memory contract is the denser pane: two thirds of the
                  column vs the history's one third. */}
              <Box
                flex="2"
                minHeight={0}
                overflow="hidden"
                borderTop="1px solid"
                borderColor={separatorColor}
              >
                <MemorySection showViewSwitcher={false} />
              </Box>
            </>
          )}
        </Flex>
      </Flex>
    );
  }

  return (
    <Flex {...containerProps} data-testid="try-assistant-container">
      <Box css={chatPanelStyles}>
        <ChatSection handleSelect={handleSelect} />
      </Box>
      {flowView && (
        <Box
          css={panelBorderLeft}
          flex={`1 1 ${SIDE_PANEL_MAX_WIDTH}`}
          minWidth={0}
          data-testid="inspector-canvas"
        >
          {selectedElement ? (
            <EventDetails event={selectedElement} onClose={clearSelectedElement} flows={flows} />
          ) : (
            <>
              {inspectorView === InspectorView.ActiveFlow && <MiddlePane />}
              {inspectorView === InspectorView.History && <HistorySection />}
              {inspectorView === InspectorView.Memory && <MemorySection />}
            </>
          )}
        </Box>
      )}
    </Flex>
  );
}
